# Test hypothesis: each input pixel maps to a 3x2 output block
def check_pixel_mapping():
    h_scale, w_scale = 3, 2

    mismatches = []
    for i in range(len(demo_in)):
        for j in range(len(demo_in[0])):
            val = demo_in[i][j]

            # Check if all pixels in the corresponding 3x2 block have the same value as val
            match = True
            for dr in range(h_scale):
                for dc in range(w_scale):
                    if demo_out[i*h_scale+dr][j*w_scale+dc] != val:
                        match = False
                        mismatches.append(((i,j), val, demo_out[i*h_scale+dr][j*w_scale+dc]))
                        break
                if not match:
                    break
            if not match:
                print(f"Mismatch at ({i},{j}): input={val}, expected block of {val}, got mixed values")

    if mismatches:
        print(f"\nTotal mismatches: {len(mismatches)}")
        for m in mismatches[:10]:
            print(f"  {m}")
    else:
        print("Perfect match! Each pixel maps to a uniform 3x2 block.")

check_pixel_mapping()

